import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Create plane geometry with 1.6:1 aspect ratio (512x320 pixels)
  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create material
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene position
  const scenePos = config.scenePosition || {};
  group.position.set(
    scenePos.x ?? 0,
    scenePos.y ?? 1.85,
    scenePos.z ?? 0
  );

  // Apply rotation
  if (scenePos.rotationXYZ) {
    group.rotation.order = 'XYZ';
    group.rotation.set(
      scenePos.rotationXYZ.x ?? 0,
      scenePos.rotationXYZ.y ?? 0,
      scenePos.rotationXYZ.z ?? 0
    );
  }

  // Apply scale
  if (scenePos.scaleXYZ) {
    group.scale.set(
      scenePos.scaleXYZ.x ?? 1,
      scenePos.scaleXYZ.y ?? 1,
      scenePos.scaleXYZ.z ?? 1
    );
  }

  // Render text content via fontAtlas
  if (config.textContent && config.textContent.length > 0) {
    const textData = config.textContent[0];
    const textMesh = ctx.fontAtlas.createMesh({
      text: textData.text || 'Atelier Noir — precise · luxury · technical',
      fontSize: 0.3, // Headline size from design tokens
      color: 0xe8ecf2, // Paper color
      anchorX: 'center',
      anchorY: 'middle',
    });

    textMesh.position.z = 0.01; // Slightly above the plane
    group.add(textMesh);
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    }
  }

  // Setup cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Setup event handlers
  group.userData.handlers = {};

  return group;
}
